using System.Text;
using UnityEditor;
using UnityEngine;

public class FishReorgTool
{
    public static void Run()
    {
        string[] pairs = new string[]
        {
            "Assets/Scripts/Module/Fish/Model/IdleHookState.cs|Assets/Scripts/Module/Fish/Model/HookState/IdleHookState.cs",
            "Assets/Scripts/Module/Fish/Model/DescendingHookState.cs|Assets/Scripts/Module/Fish/Model/HookState/DescendingHookState.cs",
            "Assets/Scripts/Module/Fish/Model/ReelingHookState.cs|Assets/Scripts/Module/Fish/Model/HookState/ReelingHookState.cs",
            "Assets/Scripts/Module/Fish/Model/LandedHookState.cs|Assets/Scripts/Module/Fish/Model/HookState/LandedHookState.cs",
            "Assets/Scripts/Module/Fish/Service/IFishBehavior.cs|Assets/Scripts/Module/Fish/Service/Behavior/IFishBehavior.cs",
            "Assets/Scripts/Module/Fish/Service/CruiseFishBehavior.cs|Assets/Scripts/Module/Fish/Service/Behavior/CruiseFishBehavior.cs",
            "Assets/Scripts/Module/Fish/Service/SchoolFishBehavior.cs|Assets/Scripts/Module/Fish/Service/Behavior/SchoolFishBehavior.cs",
            "Assets/Scripts/Module/Fish/Service/DriftFishBehavior.cs|Assets/Scripts/Module/Fish/Service/Behavior/DriftFishBehavior.cs",
            "Assets/Scripts/Module/Fish/Service/GuardFishBehavior.cs|Assets/Scripts/Module/Fish/Service/Behavior/GuardFishBehavior.cs",
            "Assets/Scripts/Module/Fish/View/IInputProvider.cs|Assets/Scripts/Module/Fish/View/Input/IInputProvider.cs",
            "Assets/Scripts/Module/Fish/View/MouseInputProvider.cs|Assets/Scripts/Module/Fish/View/Input/MouseInputProvider.cs",
            "Assets/Art/Textures/Tex_Water_Gradient.png|Assets/Art/Textures/Water/T_Water_Gradient.png"
        };

        StringBuilder sb = new StringBuilder();

        for (int i = 0; i < pairs.Length; i++)
        {
            string[] ab = pairs[i].Split('|');

            if (AssetDatabase.LoadAssetAtPath<Object>(ab[0]) == null)
            {
                sb.AppendLine("MISS  " + ab[0]);
                continue;
            }

            string folder = ab[1].Substring(0, ab[1].LastIndexOf('/'));
            ensureFolder(folder, sb);

            string error = AssetDatabase.MoveAsset(ab[0], ab[1]);
            sb.AppendLine(string.IsNullOrEmpty(error) ? "OK    " + ab[1] : "ERR   " + error);
        }

        AssetDatabase.Refresh();
        Debug.Log("[FishReorgTool]\n" + sb);
    }

    private static void ensureFolder(string folder, StringBuilder sb)
    {
        if (AssetDatabase.IsValidFolder(folder))
            return;

        string[] parts = folder.Split('/');
        string current = parts[0];

        for (int i = 1; i < parts.Length; i++)
        {
            string next = current + "/" + parts[i];

            if (!AssetDatabase.IsValidFolder(next))
            {
                bool created = !string.IsNullOrEmpty(AssetDatabase.CreateFolder(current, parts[i]));
                sb.AppendLine(created ? "MKDIR " + next : "ERRDIR " + next);
            }

            current = next;
        }
    }
}
